// Classes de la Résidence (cyberpunk, « le Bail ») : dix classes, deux sous-classes chacune.
// Caractéristiques du genre : 0 Corps, 1 Réflexes, 2 Endurance, 3 Technique, 4 Instinct, 5 Aplomb.
// Pas de magie : des implants (loués, avec un loyer en heures), le piratage (il laisse des traces) et les heures (le solde).
// Dans ce fichier, « h » veut toujours dire heures de Compteur, la monnaie ; une durée s'écrit en toutes lettres.
// Le prix des grands pouvoirs : voir « Le prix » (traces ou heures) et la section « Le Réseau et les traces » de residence-regles.ts.
// Les textes sont lus par les joueurs : aucun secret du canon (shared/canon/cyberpunk.ts) ici.
import type { ActionType, CharacterClass, Power, Recharge, Subclass } from "./rules";

const P = (level: number, name: string, action: ActionType, recharge: Recharge, effect: string, extra: Partial<Power> = {}): Power => ({ level, name, action, recharge, effect, ...extra });
const S = (id: string, name: string, pitch: string, description: string, powers: Power[]): Subclass => ({ id, name, pitch, description, powers });

/** Le rang d'un pouvoir de piratage, et ce qu'il coûte en traces ou en heures. */
const rang = (n: number) =>
  n <= 2
    ? ` Rang ${n}, sans prix.`
    : n <= 5
      ? ` Rang ${n}. S'il est le premier pouvoir de rang 3 à 5 que tu utilises depuis ton dernier repos long, il te coûte une trace ou 15 h.`
      : n <= 8
        ? ` Rang ${n}. Coûte une trace ou 60 h à chaque fois.`
        : " Rang 9. Coûte deux traces ou 80 h.";

/** Un pouvoir qui est un implant : il a un loyer mensuel en heures. */
const implant = (h: number) => ` Implant, loyer ${h} h par mois.`;

/** Un pouvoir poussé au-delà du réglage : il brûle des heures du solde. */
const surcadence = (h: number) => ` Surcadence : brûle ${h} h de ton solde.`;

const PRIX_RESEAU =
  "Un pouvoir de piratage a un rang de 1 à 9 : rang 1 et 2, gratuit ; rang 3 à 5, une trace ou 15 h, une fois par jour ; rang 6 à 8, une trace ou 60 h à chaque fois ; rang 9, deux traces ou 80 h ; à trois traces, un Huissier frappe dans l'heure.";

const PRIX_SOLO =
  "La Surcadence est le prix du Solo : tes implants peuvent tourner plus fort que leur réglage. Un pouvoir marqué « Surcadence » brûle à chaque usage les heures qu'il indique (10 h, 30 h ou 80 h). Tu peux brûler des heures que tu n'as pas : tu passes sous zéro, et tu fonds. Tes autres pouvoirs ne coûtent rien.";

